<script setup lang="ts">
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ListPanel from '../components/ListPanel.vue';
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { Plus, RefreshCw, Search } from 'lucide-vue-next';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api';
import PageHeader from '../components/PageHeader.vue';
import { useSessionStore } from '../stores/session';

const session=useSessionStore(),loading=ref(false),error=ref(''),rows=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(''),status=ref(''),type=ref(''),dialog=ref(false),saving=ref(false),options=reactive<any>({enterprises:[]});const form=reactive({title:'',enterpriseId:'',inspectionType:'ROUTINE',inspectorName:'',scheduledAt:''});const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');const canCreate=computed(()=>!isEnterprise.value&&session.user?.permissions.includes('safety:violation:write'));
const statusText=(v:string)=>({PLANNED:'待检查',COMPLETED:'已完成',RECTIFYING:'整改中',PENDING_REVIEW:'待复查',CLOSED:'已关闭'} as any)[v]??v;const typeText=(v:string)=>({ROUTINE:'日常检查',SPECIAL:'专项检查',RANDOM:'随机抽查'} as any)[v]??v;const fmt=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams({page:String(page.value),pageSize:'20'});if(q.value)p.set('q',q.value);if(status.value)p.set('status',status.value);if(type.value)p.set('type',type.value);const data=await api<any>(`/governance/inspections?${p}`);rows.value=data.items;total.value=data.total}catch(reason){error.value=reason instanceof Error?reason.message:'检查记录加载失败'}finally{loading.value=false}}
watch([q,status,type],()=>{page.value=1;load()});watch(page,load);onMounted(async()=>{Object.assign(options,await api('/governance/options'));await load()});
function openCreate(){Object.assign(form,{title:'',enterpriseId:options.enterprises[0]?.id??'',inspectionType:'ROUTINE',inspectorName:session.user?.displayName??'',scheduledAt:new Date(Date.now()+86400000).toISOString().slice(0,16)});dialog.value=true}
async function create(){if(!form.title||!form.enterpriseId||!form.inspectorName||!form.scheduledAt)return ElMessage.warning('请完整填写检查计划');saving.value=true;try{await api('/governance/inspections',{method:'POST',body:JSON.stringify({...form,scheduledAt:new Date(form.scheduledAt).toISOString()})});ElMessage.success('检查计划已创建');dialog.value=false;await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'创建失败')}finally{saving.value=false}}
async function act(row:any,action:string){const label=({COMPLETE:'完成检查',REQUEST_RECTIFICATION:'下达整改',SUBMIT_RECTIFICATION:'提交整改反馈',CLOSE:'复查关闭'} as any)[action];let content='';try{content=(await ElMessageBox.prompt(`填写${label}意见`,label,{inputType:'textarea',inputValidator:(v:string)=>v?.trim()?true:'请输入处理内容'})).value}catch{return}const payload:any={action,content};if(action==='REQUEST_RECTIFICATION')payload.dueAt=new Date(Date.now()+7*86400000).toISOString();if(action==='COMPLETE')payload.issueCount=0;try{await api(`/governance/inspections/${row.id}/actions`,{method:'POST',body:JSON.stringify(payload)});ElMessage.success(`${label}成功`);await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'操作失败')}}

function resetQueryFilters() {
  q.value = '';
  type.value = '';
  status.value = '';
  page.value = 1;
  load();
}
</script>
<template><section><PageHeader :title="isEnterprise?'检查与整改':'检查管理'" :count="total"/><QueryPanel :loading="loading" @search="load" @reset="resetQueryFilters">
<QueryField label="关键词" keyword><el-input aria-label="关键词" v-model="q" :prefix-icon="Search" clearable placeholder="搜索检查编号、标题、企业或人员"/></QueryField>
<QueryField label="类型"><el-select aria-label="类型" v-model="type" clearable placeholder="全部类型"><el-option label="日常检查" value="ROUTINE"/><el-option label="专项检查" value="SPECIAL"/><el-option label="随机抽查" value="RANDOM"/></el-select></QueryField>
<QueryField label="状态"><el-select aria-label="状态" v-model="status" clearable placeholder="全部状态"><el-option label="待检查" value="PLANNED"/><el-option label="已完成" value="COMPLETED"/><el-option label="整改中" value="RECTIFYING"/><el-option label="待复查" value="PENDING_REVIEW"/><el-option label="已关闭" value="CLOSED"/></el-select></QueryField>
</QueryPanel>
<ListPanel :title="(isEnterprise?'检查与整改':'检查管理') + '列表'" :total="error ? undefined : (total)">
<template #actions><el-button v-if="canCreate" type="primary" :icon="Plus" @click="openCreate">新增检查</el-button></template>
<div v-if="error" class="error-state"><strong>检查记录暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><el-table v-else v-loading="loading" :data="rows" empty-text="暂无符合条件的检查记录"><el-table-column label="检查任务" min-width="240"><template #default="{row}"><div class="identity-cell"><strong>{{row.title}}</strong><span>{{row.businessNo}}</span></div></template></el-table-column><el-table-column label="类型" width="100"><template #default="{row}">{{typeText(row.inspectionType)}}</template></el-table-column><el-table-column v-if="!isEnterprise" label="企业" min-width="190"><template #default="{row}">{{row.enterprise.name}}</template></el-table-column><el-table-column label="检查人员" width="120" prop="inspectorName"/><el-table-column label="计划时间" width="165"><template #default="{row}">{{fmt(row.scheduledAt)}}</template></el-table-column><el-table-column label="问题数" width="80" prop="issueCount"/><el-table-column label="整改期限" width="120"><template #default="{row}">{{row.rectificationDueAt?.slice(0,10)||'—'}}</template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag effect="plain" :type="row.status==='CLOSED'?'success':row.status==='RECTIFYING'||row.status==='PENDING_REVIEW'?'warning':'info'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="175" fixed="right"><template #default="{row}"><template v-if="!isEnterprise"><el-button v-if="row.status==='PLANNED'" link type="primary" @click="act(row,'COMPLETE')">完成检查</el-button><el-button v-if="['PLANNED','COMPLETED','PENDING_REVIEW'].includes(row.status)" link type="warning" @click="act(row,'REQUEST_RECTIFICATION')">要求整改</el-button><el-button v-if="['COMPLETED','PENDING_REVIEW'].includes(row.status)" link type="success" @click="act(row,'CLOSE')">关闭</el-button></template><el-button v-else-if="row.status==='RECTIFYING'" link type="primary" @click="act(row,'SUBMIT_RECTIFICATION')">提交整改</el-button></template></el-table-column></el-table><div class="pagination-row"><span>当前显示 {{rows.length}} / {{total}}</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next"/></div>
</ListPanel>
<el-dialog v-model="dialog" title="新增检查计划" width="620px"><div class="form-grid"><el-form-item class="form-span-2" label="检查标题" required><el-input v-model="form.title"/></el-form-item><el-form-item label="检查类型"><el-select v-model="form.inspectionType"><el-option label="日常检查" value="ROUTINE"/><el-option label="专项检查" value="SPECIAL"/><el-option label="随机抽查" value="RANDOM"/></el-select></el-form-item><el-form-item label="被检查企业" required><el-select v-model="form.enterpriseId" filterable><el-option v-for="x in options.enterprises" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="检查人员" required><el-input v-model="form.inspectorName"/></el-form-item><el-form-item label="计划时间" required><el-date-picker v-model="form.scheduledAt" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item></div><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建计划</el-button></template></el-dialog></section></template>
